(6928734, 1043259, 30861, '<td valign="top">Beats the heck out of MY knife-slip attempt in 2005 LOL. <a href="//www.dpchallenge.com/image.php?IMAGE_ID=145010" rel="nofollow" target="_blank"><img alt="'' . substr(''//images.dpchallenge.com/images_challenge/0-999/307/120/Copyrighted_Image_Reuse_Prohibited_145010.jpg'', strrpos(''//images.dpchallenge.com/images_challenge/0-999/307/120/Copyrighted_Image_Reuse_Prohibited_145010.jpg'', ''/'') + 1) . ''" border="0" src="//images.dpchallenge.com/images_challenge/0-999/307/120/Copyrighted_Image_Reuse_Prohibited_145010.jpg"/></a> <br/> <br/>Love the expression. Congrats on the ribbon!</td>', 'Beats the heck out of MY knife-slip attempt in 2005 LOL.   Love the expression. Congrats on the ribbon!', '2012-12-10 00:48:51.000000', NULL, 0),
